	@Test
	void twoTimerLaunchRejectionsDoNotKillAnUnrelatedDeadline() throws Exception {
		Source anchorSource = new Source(false), failingSource = new Source(false), otherSource = new Source(false);
		anchorSource.releaseAll();
		failingSource.releaseAll();
		otherSource.releaseAll();
		RejectedExecutionException first = new RejectedExecutionException("timer cancellation launch");
		RejectedExecutionException fallback = new RejectedExecutionException("timer fallback launch");
		CountDownLatch rejected = new CountDownLatch(2);
		AtomicInteger attempts = new AtomicInteger();
		TimeLimitIteration.AsyncLauncher launcher = task -> {
			int attempt = attempts.incrementAndGet();
			if (attempt <= 2) {
				rejected.countDown();
				throw attempt == 1 ? first : fallback;
			}
			launch(failingSource, task);
		};
		RuntimeException timeout = new IllegalStateException("timed out");
		TimeLimitIteration<String> anchor = timed(anchorSource, task -> launch(anchorSource, task), timeout);
		TimeLimitIteration<String> failing = new TimeLimitIteration<>(failingSource, 1, launcher) {
			@Override
			protected void throwInterruptedException() {
				throw timeout;
			}
		};
		AtomicReference<TimeLimitIteration<String>> later = new AtomicReference<>();
		try (AutoCloseable anchorCleanup = () -> releaseAndClose(anchorSource, anchor);
				AutoCloseable failingCleanup = () -> releaseAndClose(failingSource, failing);
				AutoCloseable laterCleanup = () -> {
					if (later.get() != null)
						releaseAndClose(otherSource, later.get());
				}) {
			assertTrue(rejected.await(5, TimeUnit.SECONDS), "both launches must reject on the shared timer");
			later.set(assertDoesNotThrow(() -> new TimeLimitIteration<String>(otherSource, 20) {
				@Override
				protected void throwInterruptedException() {
					throw timeout;
				}
			}, "the shared timer must still accept another deadline"));
			assertTrue(otherSource.callbackEntered.await(5, TimeUnit.SECONDS), "another deadline must still run");
			Throwable observed = taskOutcome(startTask(failingSource, "later-pull", failing::hasNext));
			assertSame(timeout, observed);
			assertFailuresVisible(first, fallback, observed);
		}
	}

	private static TimeLimitIteration<String> timed(Source source, TimeLimitIteration.AsyncLauncher launcher,
			RuntimeException timeout) {
		return new TimeLimitIteration<>(source, 60_000, 25, 25, launcher) {
			@Override
			protected void throwInterruptedException() {
				throw timeout;
			}
		};
	}

	private static Throwable signal(Source source, TimeLimitIteration<String> limited) throws Exception {
		return taskOutcome(startTask(source, "signal", () -> {
			limited.interrupt();
			return null;
		}));
	}

	private static final class TaskAttempt<T> {
		final FutureTask<T> future;
		final Thread thread;
		boolean consumed;

		TaskAttempt(FutureTask<T> future, Thread thread) {
			this.future = future;
			this.thread = thread;
		}
	}

	private static <T> TaskAttempt<T> startTask(Source source, String name, Callable<T> action) {
		FutureTask<T> future = new FutureTask<>(action);
		Thread thread = Thread.ofVirtual().name("test-" + name).unstarted(future);
		TaskAttempt<T> attempt = new TaskAttempt<>(future, thread);
		source.attempts.add(attempt);
		thread.start();
		return attempt;
	}

	private static void launch(Source source, Runnable action) {
		Thread thread = Thread.ofVirtual().name("test-launch").unstarted(action);
		source.launchThreads.add(thread);
		thread.start();
	}

	private static TaskAttempt<Void> closeOnVirtualThread(Source source, TimeLimitIteration<String> limited) {
		return startTask(source, "close", () -> {
			limited.close();
			return null;
		});
	}

	private static Throwable taskOutcome(TaskAttempt<?> attempt) throws Exception {
		Throwable failure = outcome(attempt.future);
		attempt.consumed = true;
		return failure;
	}

	private static void runAccepted(Source source, Iterable<Runnable> tasks) throws Exception {
		for (Runnable task : tasks) {
			Throwable failure = taskOutcome(startTask(source, "accepted", () -> {
				task.run();
				return null;
			}));
			if (failure != null)
				throw new AssertionError("accepted task failed", failure);
		}
	}

	private static void releaseAndClose(Source source, TimeLimitIteration<String> limited) throws Exception {
		source.releaseAll();
		closeOnVirtualThread(source, limited);
		Throwable failure = null;
		for (TaskAttempt<?> attempt : source.attempts) {
			try {
				Throwable problem = outcome(attempt.future);
				if (!attempt.consumed && problem != null)
					failure = combine(failure, problem);
			} catch (TimeoutException unresolved) {
				failure = combine(failure, unresolvedThread(attempt.thread, unresolved));
			}
		}
		for (Thread thread : source.launchThreads) {
			thread.join(3000);
			if (thread.isAlive())
				failure = combine(failure, unresolvedThread(thread, null));
		}
		if (failure instanceof Exception exception)
			throw exception;
		if (failure instanceof Error error)
			throw error;
	}

	private static AssertionError unresolvedThread(Thread thread, Throwable cause) {
		System.err.println("UNRESOLVED_TEST_THREAD thread=" + thread + " stack="
				+ java.util.Arrays.toString(thread.getStackTrace()));
		return new AssertionError("test-owned thread did not return after gate release", cause);
	}

	private static void awaitObserved(CountDownLatch latch) {
		try {
			if (!latch.await(5, TimeUnit.SECONDS))
				throw new AssertionError("launcher did not reach expected gate");
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("launcher interrupted before expected gate", interrupted);
		}
	}

	private static Throwable combine(Throwable primary, Throwable secondary) {
		if (primary == null)
			return secondary;
		if (secondary != primary)
			primary.addSuppressed(secondary);
		return primary;
	}

	private static Throwable outcome(Future<?> future) throws Exception {
		try {
			future.get(3, TimeUnit.SECONDS);
			return null;
		} catch (ExecutionException failure) {
			return failure.getCause();
		}
	}

	private static void assertFailuresVisible(Throwable first, Throwable second, Throwable... outcomes) {
		boolean firstVisible = false, secondVisible = false;
		for (Throwable outcome : outcomes) {
			firstVisible |= contains(outcome, first);
			secondVisible |= contains(outcome, second);
		}
		assertTrue(firstVisible, "the first launch failure must remain observable");
		assertTrue(secondVisible, "the fallback launch failure must remain observable");
	}

	private static boolean contains(Throwable root, Throwable target) {
		if (root == null)
			return false;
		Set<Throwable> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		ArrayDeque<Throwable> pending = new ArrayDeque<>();
		pending.add(root);
		while (!pending.isEmpty()) {
			Throwable current = pending.remove();
			if (current == target)
				return true;
			if (!seen.add(current))
				continue;
			if (current.getCause() != null)
				pending.add(current.getCause());
			Collections.addAll(pending, current.getSuppressed());
		}
		return false;
	}

	private static final class Source implements CloseableIteration<String>, CooperativeCancellation {
		final boolean accepts;
		final CountDownLatch pullEntered = new CountDownLatch(1), releasePull = new CountDownLatch(1);
		final CountDownLatch callbackEntered = new CountDownLatch(1), callbackFinished = new CountDownLatch(1),
				releaseCallback = new CountDownLatch(1);
		final CountDownLatch closeEntered = new CountDownLatch(1), closeFinished = new CountDownLatch(1),
				releaseClose = new CountDownLatch(1);
		final AtomicInteger requests = new AtomicInteger(), closes = new AtomicInteger(),
				lateRequests = new AtomicInteger();
		final AtomicBoolean retired = new AtomicBoolean();
		final CopyOnWriteArrayList<TaskAttempt<?>> attempts = new CopyOnWriteArrayList<>();
		final CopyOnWriteArrayList<Thread> launchThreads = new CopyOnWriteArrayList<>();

		Source(boolean accepts) {
			this.accepts = accepts;
		}

		@Override
		public boolean hasNext() {
			pullEntered.countDown();
			await(releasePull);
			return true;
		}

		@Override
		public String next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean requestCancellation() {
			if (retired.get())
				lateRequests.incrementAndGet();
			requests.incrementAndGet();
			callbackEntered.countDown();
			await(releaseCallback);
			callbackFinished.countDown();
			return accepts;
		}

		@Override
		public void close() {
			closes.incrementAndGet();
			closeEntered.countDown();
			await(releaseClose);
			retired.set(true);
			closeFinished.countDown();
		}

		void releaseAll() {
			releasePull.countDown();
			releaseCallback.countDown();
			releaseClose.countDown();
		}
	}

	private static void await(CountDownLatch latch) {
		boolean interrupted = false;
		while (true)
			try {
				latch.await();
				break;
			} catch (InterruptedException e) {
				interrupted = true;
			}
		if (interrupted)
			Thread.currentThread().interrupt();
	}
